  /* =================== BANCO DE PREGUNTAS =================== */
  const STDF = [1, 2, 3, 5, 7.5, 10, 15, 20, 25, 30];
  const TAB = [['14 AWG', 15], ['12 AWG', 20], ['10 AWG', 30], ['8 AWG', 40], ['6 AWG', 55]];
  const CABLE = [['18 AWG', 0.021], ['16 AWG', 0.0132], ['14 AWG', 0.0083]];
  const fv = x => f(x, x < 1 ? 3 : 2), fp = x => f(x, 2);
  const gen = {
    m3corriente: rnd => { const c = pick(rnd, [['un motor de CD', 12, [6, 12, 18, 24, 36, 48]], ['una tira de LED', 12, [6, 12, 24, 30]], ['un motor de CD', 24, [24, 48, 72, 96, 120]], ['una parrilla', 127, [254, 381, 508, 635, 1270]], ['un foco incandescente', 127, [60, 75, 100]]]), P = pick(rnd, c[2]), V = c[1], I = P / V;
      return { q: '¿Qué corriente consume ' + c[0] + ' de ' + P + ' W que trabaja a ' + V + ' V?', op: ops(f(I, 2) + ' A', [f(P * V, 0) + ' A', f(V / P, 2) + ' A', f(I * 10, 2) + ' A'], [f(I / 2, 2) + ' A', f(I + 1, 2) + ' A', f(I * 3, 2) + ' A']), r: 'I = P / V = ' + P + ' / ' + V + ' = ' + f(I, 2) + ' A.' }; },
    m3calibre: rnd => { const I = pick(rnd, [6, 8, 10, 11, 13, 14, 15, 17, 20, 22, 25, 28, 30, 35, 40]), dd = I * 1.25, ok = TAB.find(x => x[1] >= dd - 1e-9), sin = TAB.find(x => x[1] >= I - 1e-9), k = TAB.indexOf(ok);
      return { q: 'Un motor de 220 V tiene ' + I + ' A de corriente de placa. Con la tabla de cobre a 60 °C (14 AWG: 15 A · 12 AWG: 20 A · 10 AWG: 30 A · 8 AWG: 40 A · 6 AWG: 55 A), ¿qué calibre mínimo le corresponde a su conductor?', op: ops(ok[0], [sin[0], (TAB[k - 1] || TAB[k + 2])[0], (TAB[k + 1] || TAB[k - 2])[0]], TAB.map(x => x[0])), r: 'El conductor de un motor se elige al 125 %: ' + I + ' × 1.25 = ' + f(dd, 2) + ' A → el primer calibre que aguanta al menos eso es ' + ok[0] + ' (' + ok[1] + ' A).' }; },
    m3caida: rnd => { const V = pick(rnd, [12, 24]), L = pick(rnd, [2, 3, 5, 8, 10]), I = pick(rnd, [1, 2, 3, 4]), w = pick(rnd, CABLE), dv = 2 * L * w[1] * I, p = dv / V * 100;
      const t = (x, y) => fv(x) + ' V (' + fp(y) + ' %)';
      return { q: 'Un motor de ' + V + ' V consume ' + I + ' A y está a ' + L + ' m de la fuente, con cable ' + w[0] + ' (' + f(w[1] * 1000, 1) + ' mΩ por metro). ¿Cuánto voltaje se pierde en el cable (ida y vuelta) y qué porcentaje del voltaje es?', op: ops(t(dv, p), [t(dv / 2, p / 2), t(dv * 2, p * 2), t(L * w[1], L * w[1] / V * 100)], [t(dv, p * 10), t(dv * 10, p * 10)]), r: 'V = 2 · L · R · I = 2 × ' + L + ' × ' + f(w[1], 4) + ' × ' + I + ' = ' + fv(dv) + ' V; ' + fv(dv) + ' / ' + V + ' × 100 = ' + fp(p) + ' %' + (p > 3 ? ': pasa del 3 % recomendado, conviene un cable más grueso.' : ': queda dentro del 3 % recomendado.') }; },
    m3fusible: rnd => { const m = pick(rnd, [0.8, 1.2, 1.5, 2, 2.5, 3, 4, 6]), nr = pick(rnd, [1, 2, 3]), nl = pick(rnd, [1, 2, 3]), It = m + nr * 0.1 + nl * 0.02, dd = It * 1.25, ok = STDF.find(x => x >= dd - 1e-9), sin = STDF.find(x => x >= It - 1e-9), k = STDF.indexOf(ok);
      const A = x => f(x, 1) + ' A';
      return { q: 'Un tablero de 12 V tiene un motor de ' + f(m, 1) + ' A, ' + nr + (nr > 1 ? ' relevadores' : ' relevador') + ' de 0.1 A y ' + nl + (nl > 1 ? ' luces' : ' luz') + ' piloto de 0.02 A. Con un margen de 25 %, ¿qué fusible comercial eliges? (1, 2, 3, 5, 7.5, 10, 15 o 20 A)', op: ops(A(ok), [A(sin), A(STDF[k - 1]), A(STDF[k + 2])], STDF.map(A)), r: 'Corriente total = ' + f(m, 1) + ' + ' + nr + ' × 0.1 + ' + nl + ' × 0.02 = ' + f(It, 2) + ' A; con 25 % de margen: ' + f(It, 2) + ' × 1.25 = ' + f(dd, 2) + ' A → el fusible comercial inmediato superior es de ' + A(ok) + '.' }; },
    m3bobina: rnd => { const V = pick(rnd, [12, 24]), R = V === 12 ? pick(rnd, [80, 160, 288, 400]) : pick(rnd, [576, 1150, 1600]), I = V / R * 1000, P = V * V / R;
      const t = (i, p) => f(i, 1) + ' mA · ' + f(p, 2) + ' W';
      return { q: 'La bobina de un relevador de ' + V + ' V CD mide ' + R + ' Ω. ¿Cuánta corriente consume y qué potencia?', op: ops(t(I, P), [t(R / V, R / 1000), t(I / 10, P / 10), t(I, V * I)], [t(I * 2, P * 2), t(I / 2, P / 2)]), r: 'I = V / R = ' + V + ' / ' + R + ' = ' + f(I / 1000, 4) + ' A = ' + f(I, 1) + ' mA; P = V² / R = ' + V + '² / ' + R + ' = ' + f(P, 2) + ' W.' }; }
  };
